          if (this.t >= 26) { this.phase = 'leap'; this.t = 0; L.vy = -15; L.onGround = false; L.vx = (tx - L.face * 60 - L.x) / 28; L.face = Math.sign(tx - L.x) || L.face; sfx.whoosh(); }
          break;
