        if (chant) { popText(this.x - this.face * 40, this.y - 160, chant, '#ef4444', 40); sfx.chant((t - 40) / 14); }
        for (let i = 0; i < 6; i++) { const a = rand(0, TAU), r = rand(140, 320); particles.push({ x: hand.x + Math.cos(a) * r, y: hand.y + Math.sin(a) * r, z: rand(-100, 100), vx: -Math.cos(a) * r / 14, vy: -Math.sin(a) * r / 14, vz: 0, life: 14, max: 14, color: ['#ef4444', '#dc2626', '#f97316', '#fde047'][i % 4], size: 9, g: 0 }); }
        game.fireBall = { x: hand.x, y: hand.y, r: 10 + this.orb * 75, twin: false };
