          if (boss.floorHp) { popText(boss.x, boss.y - 220 * boss.k, 'IT SHRUGS IT OFF!', '#93c5fd', 44); boss.takeHit(boss.hp, 0, 0, boss.x, boss.y - 150 * boss.k); this.endSpecial(); return; }
          popText(boss.x, boss.y - 220 * boss.k, 'ONE SHOT!', '#ef4444', 64);
