  class CivBoss extends ShadowKnight {
    constructor(lv, key) {
      super(lv); const C = CIV_LOOKS[key]; this.civ = key; this.isCiv = true;
      this.hair = new THREE.Color(C.hair); this.band = new THREE.Color(C.band); this.shirt = new THREE.Color(C.shirt); this.pants = new THREE.Color(C.pants); this.spiky = C.spiky;
      this.renderScale = C.scale; this.dmgMul = C.dmg; this.blockChance = 0.33; if (C.skin) this.skin = new THREE.Color(C.skin);
    }
    armorPart() { return 0; }
    get reach() { return 125 * this.renderScale; }
    get hurtbox() {
      const hb = super.hurtbox, s = this.renderScale || 1;
      if (!hb) return hb;
      return { x: this.x - (this.x - hb.x) * s, y: GROUND - (GROUND - hb.y) * s, w: hb.w * s, h: hb.h * s };
    }
    strike(hero, dmg, reach, kind) { return super.strike(hero, dmg, reach * (this.renderScale || 1), kind); }
    think(hero) { // no dark magic: just fists and footwork
      if (this.energy >= 100) this.energy = 0;
      super.think(hero);
      if (this.state === 'crescent') { this.setState('approach'); this.wait = 30; }
    }
  }
