      if (isS10(this.level) || isS11(this.level)) { this.s10Down(); return; }
      if (isS12(this.level)) { this.s12Down(); return; }
      if (isS13(this.level)) { this.s13Down(); return; }
      if (isS14(this.level)) { this.s14Down(); return; }
