      if (this.level === VEGETA_LV) { const b = this.boss; b.alive = true; b.hp = 1; b.deathT = 0; b.state = 'idle'; this.startVegetaEnd(); return; }
      if (this.level === TITAN_LV) { const b = this.boss; b.alive = true; b.hp = 1; b.deathT = 0; b.state = 'idle'; this.startTeamKame(); return; }
