        this.beam2 = { x0: g.x + g.face * 70, x1: g.face > 0 ? W + 400 : -400, y: g.y - 150, t: tt, dir: g.face, through: true, size: 2.0, owner: g };
        if (ft === 6) { b.setState('hurt'); hitstop = 8; flash = 10; }
        if (ft > 6 && ft < 72) { b.x = clamp(b.x + h.face * 1.6, ARENA_L + 60, ARENA_R - 60); if (ft % 4 === 0) { burst(b.x + rand(-60, 60), b.y - rand(80, 380), 18, ft % 8 ? '#f97316' : '#e879f9', 11, 6, 0, 18); burst(b.x, b.y - 200, 10, '#ffffff', 8, 5, 0, 14); } shakeIt(10); }
