      if (t >= 440) { this.souls.round = 2; this.saga = null; this.mode = 'fight'; this.modeT = 0; h.setState('idle'); h.inv = 30; h.hp = Math.min(h.maxHp, h.hp + h.maxHp * 0.3); popText(W / 2, 150, "ROUND 2  ·  KANE'S SOUL", '#c084fc', 40); return; }
      this.sagaTail();
