      h.face = Math.sign(b.x - h.x) || 1; h.animate(); b.face = Math.sign(h.x - b.x) || -1; b.animate();
      if (t === 10) popText(b.x, GROUND - 300, 'KANE: Hhh... that hit... I can... SEE again...', '#c084fc', 22);
