        flash = 16; shakeIt(24); sfx.boom(); popText(W / 2, 140, '*CRACK*', '#fde047', 54);
        burst(b.x, b.y - 130, 120, '#fde047', 14, 7, -0.1, 40); burst(b.x, b.y - 130, 60, '#7e22ce', 12, 6, 0.2, 30); this.rings.push({ x: b.x, y: GROUND, r: 10, life: 36, color: '253,224,71' });
