        if (this.time % 3 === 0) particles.push({ x: m.x + rand(-25, 25), y: GROUND - 4, z: rand(-20, 20), vx: 0, vy: -0.5, vz: 0, life: 8, max: 8, color: '#22c55e', size: 6, g: 0 }); // where it will land
