      if (t > 50 && t < 200) { shakeIt(3); if (t % 3 === 0) burst(b.x + rand(-60, 60) * b.renderScale, b.y - rand(40, 240) * b.renderScale, 3, t % 6 ? '#4ade80' : '#ffffff', 6, 5, 0, 14); }
      if (t === 60) popText(b.x, GROUND - 540, 'VORATH: What... the souls inside me... they are FIGHTING me!', '#4ade80', 22);
      const SP = { 90: ['THE WHITE WOLF', '#e0f2fe'], 115: ['THE BLACK LION', '#d4a017'], 140: ['THE PHOENIX', '#fb923c'], 165: ['THE GOLDEN DRAGON', '#fde047'] }[t];
