        if (ft === 84) { // vorath comes apart
          b.knockdown(d); b.vx = d * 4; b.stayDown = true; this.spirits8 = [];
          burst(b.x, b.y - 250, 220, '#4ade80', 18, 8, 0.1, 54); burst(b.x, b.y - 250, 140, '#ffffff', 16, 8, 0, 50); burst(b.x, b.y - 250, 90, '#c084fc', 14, 7, 0, 40);
          sfx.boom(); flash = 24; shakeIt(44); for (const [r, c] of [[10, '74,222,128'], [-120, '233,213,255'], [-240, '255,255,255']]) this.rings.push({ x: b.x, y: GROUND, r, life: 44, color: c });
        }
        h.orb = ft < 90 ? 1 : Math.max(0, 1 - (ft - 90) / 8);
