      if (t > FIRE + 84) { b.update(h); b.renderScale = Math.max(1.12, b.renderScale - 0.01); }
      if (t === FIRE + 150) popText(b.x, GROUND - 260, 'VORATH: Spirits... do not... d—', '#4ade80', 24);
      if (t > FIRE + 200 && t < FIRE + 300) { b.y += 2.5; if (t % 2 === 0) particles.push({ x: b.x + rand(-80, 80), y: GROUND - rand(0, 40), z: rand(-30, 30), vx: 0, vy: -rand(3, 7), vz: 0, life: 40, max: 40, color: Math.random() < 0.5 ? '#4ade80' : '#ffffff', size: rand(6, 10), g: -0.02 }); }
      if (t === FIRE + 240) popText(W / 2, 140, 'VORATH IS GONE. FOREVER.', '#e9d5ff', 48);
