      for (let i = 0; i < 110; i++) { const life = Math.floor(rand(36, 72)); particles.push({ x: f.x + rand(-36, 36) * k, y: fy - rand(0, 225) * k, z: rand(-30, 30), vx: rand(0.6, 6), vy: -rand(0, 2.2), vz: rand(-1, 1), life, max: life, color: ['#a8a29e', '#78716c', '#d6d3d1', '#fde68a'][i % 4], size: rand(3, 7.5), g: -0.008 }); }
