      const d = Math.sign(b.x - h.x) || 1; if (Math.abs(b.x - h.x) > 240) h.x = b.x - d * 200; h.face = d; b.face = -d; if (h.form !== 'asura') this.setForm(h, 'asura'); h.setState('idle');
