          fire(b.x, b.y - 100, 3);
          E.face = side; E.x = lerp(b.x - side * 420, b.x + side * 420, ease(u)); E.y = b.y - 120 - Math.sin(u * Math.PI) * 80; E.flapSpeed = 0.15; E.bank = -0.3;
