          if (t === 10) popText(b.x, b.y - 250, 'HAHAHA... YOU THINK THIS IS OVER?', '#f87171', 30);
          if (t % 20 === 0) burst(b.x, b.y - 100, 12, '#7f1d1d', 5, 6, -0.1, 30);
          if (t >= 90) this.sagaStage('call');
