    const c = SCENES[lv];
    scene.fog = new THREE.Fog(c.fog[0], c.fog[1], c.fog[2]);
    scene.background = new THREE.Color(c.sky[1]);
    scene.environment = envFor(lv);
    hemi.color.set(c.hemi[0]); hemi.groundColor.set(c.hemi[1]); hemi.intensity = c.hemi[2];
