        for (let i = 0; i < 46; i++) {
          const x = -72 + R() * 128, a = (R() - 0.5) * 2.6, side = R() < 0.5 ? -1 : 1;
          part(m.body, G.sphere, mk, [x, 77 + Math.sin(a) * 24, side * Math.cos(a) * 27], big ? [4.5, 4.5, 2.4] : [2.6, 2.6, 2]);
        }
