    part(m.head, G.box, plate, [4, 16, 0], [22, 4, 18]); // head plate
    for (const z of [-1, 1]) part(m.head, G.cone, dark, [-4, 22, z * 9], [3, 14, 3], [z * 0.25, 0, -0.3]); // fin ears
    for (const leg of m.legs) part(leg.up, G.sphere, dark, [0, 0, 0], 9); // joints
