      text(L.key, x + 7, CARD.y + 54, Math.min(15, (CARD.w - 12) / (L.key.length * 0.62)), ['#4ade80', '#fbbf24', '#ef4444', '#c084fc', '#f87171', '#e879f9', '#38bdf8', '#facc15', '#fb923c', '#bfdbfe', '#a3e635', '#4ade80', '#38bdf8', '#7dd3fc', '#e0f2fe', '#fde047', '#fdba74', '#fef08a', '#bae6fd', '#f8fafc', '#38bdf8', '#fde047', '#f97316', '#c084fc', '#fcd34d', '#a855f7', '#60a5fa', '#ef4444', '#facc15', '#f472b6', '#60a5fa', '#f87171', '#f9a8d4', '#facc15', '#a78bfa', '#fb923c', '#fde047', '#fdba74', '#86efac', '#fde047', '#7dd3fc', '#f87171', '#c084fc', '#fb923c', '#a855f7', '#bfdbfe', '#e0e7ff', '#e879f9', '#60a5fa', '#fb923c', '#4ade80', '#a78bfa', '#38bdf8', '#e5e7eb', '#86efac', '#fde047', '#f9a8d4', '#f87171', '#fbbf24', '#5eead4', '#22d3ee', '#c084fc', '#fde68a', '#a5b4fc', '#fde047', '#fb923c', '#fca5a5', '#a78bfa', '#f9a8d4', '#fca5a5', '#ef4444', '#f87171', '#34d399', '#fbbf24', '#dc2626', '#9ca3af', '#5eead4', '#fb923c', '#a78bfa', '#fde047', '#9ca3af', '#5eead4', '#a3a3a3', '#f97316', '#fda4af'][i], 'left');
