          if (C.spiky) for (let k = 0; k < 5; k++) { ctx.beginPath(); ctx.moveTo(36 + k * 18, 44); ctx.lineTo(45 + k * 18, 14); ctx.lineTo(54 + k * 18, 44); ctx.fill(); }
